--1.what is the total revenue generated by male vs. female customers?
select gender,sum(purchase_amount) as revenue from customer 
group by gender;
--2.which customers used a discount but still spent more than average purchase amount?
select customer_id,purchase_amount from customer where
discount_applied='Yes'
and purchase_amount>=(select avg(purchase_amount) 
from customer);
--3.what are the top 5 products with the highest average review rating?
select item_purchased,ROUND(avg(review_rating::numeric),2)
as "Average Product Rating" 
from customer group by item_purchased
order by "Average Product Rating" desc limit 5;
--4.compare the avg purchase amounts between standard and express shipping.
select shipping_type,ROUND(avg(purchase_amount),2) 
from customer where shipping_type 
in ('Standard','Express')
group by shipping_type;
--5.Do subscribed customer spend more?compare average spend and total revenue between subscribers
select subscription_status,count(customer_id) as total_customers,
ROUND(avg(purchase_amount),2) as avg_spend,
ROUND(SUM(purchase_amount),2) as total_revenue from customer group by
subscription_status order by total_revenue,avg_spend desc;
--6.Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased,ROUND(100*sum(case when discount_applied='Yes' 
then 
1 else 0 end)/count(*),2)
as discount_rate from customer 
group by item_purchased order by discount_rate desc limit 5;
--7.Segment customers into New,Returning, and Loyal
--based on their total number of previous purchases ,and 
--show the count of each segment
select case when previous_purchases=1 
then 'New'
WHEN previous_purchases between 2 and 10 then 'Returning'
else 'Loyal' end as customer_segment,count(*) as "no of customers" 
from customer
group by customer_segment;
--8.What are the top 3 most purchased products within each category?
with item_counts as (select category,item_purchased,
count(customer_id) as total_orders,
ROW_NUMBER() over(partition by category order by 
count(customer_id) desc)as item_rank from customer 
group by category,item_purchased)
select item_rank,category,item_purchased,total_orders 
from item_counts where item_rank<=3;
--9.Are customers who are repeat buyers(more than 5 previous purchases)
--also likely to subscribe?
select subscription_status,count(customer_id) as repeat_buyers
from customer 
where previous_purchases>5 group by subscription_status;
--10 what is the revenue contribution of each age group?
select age_group,sum(purchase_amount) as total_revenue
from customer group by age_group order by total_revenue desc;









--Q1 — Who are the most valuable customers?
--Business question
--Which customer segments contribute the most to total revenue?
--The idea is to identify whether customers who are New,
--Returning, or Loyal contribute differently to the overall
--purchase amount.
SELECT
    CASE
        WHEN previous_purchases = 1 THEN 'New'
        WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
        ELSE 'Loyal'
    END AS customer_segment,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY customer_segment;